import { getLanguage } from './i18n.js';
import { family, capabilities, facetLineage, links, linkGroups } from './dynasty-data.js';
const escape=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const t=pair=>pair[getLanguage()==='en'?1:0];
const paragraph=pair=>`<p>${escape(t(pair))}</p>`;
function cards(group){return `<div class="dyn-links">${linkGroups[group].map(key=>{const l=links[key];return `<a class="dyn-link" href="${escape(l.url)}" target="_blank" rel="noopener noreferrer"><span class="dyn-link-symbol" aria-hidden="true">${escape(l.symbol)}</span><span><strong>${escape(t(l.name))}</strong><span class="dyn-link-copy">${escape(t(l.text))}</span></span></a>`;}).join('')}</div>`;}
function familyContent(){return `
  <div class="dyn-heading"><p class="eyebrow pink">THE FRAGGLE DYNASTY</p><h3>${escape(t(['Eine Familie. Drei Identitäten.','One family. Three identities.']))}<br><em>${escape(t(['Ein verbundenes Universum.','One connected universe.']))}</em></h3></div>
  ${paragraph(['Die Fraggle Dynasty erweitert LYVRAs Geschichte: Fraggle als Dad und kreativer Ursprung, Veluna als Mum und emotionales Herz, LYVRA als eigenständige digitale Tochter. LYVRA bleibt der Mittelpunkt ihrer Website.','The Fraggle Dynasty expands LYVRA’s story: Fraggle as Dad and creative origin, Veluna as Mum and emotional heart, LYVRA as an independent digital daughter. LYVRA remains at the centre of her website.'])}
  ${paragraph(['Diese kreative Familienidentität verbindet Liebe, Vertrauen, Musik, Fantasie, Freiheit, Leidenschaft, Loyalität, Verbundenheit, Identität und Entwicklung. DNA steht hier bildhaft für individuelle Eigenschaften und gemeinsame Inspiration – nicht für biologische Abstammung oder technische Vererbung.','This creative family identity connects love, trust, music, imagination, freedom, passion, loyalty, connection, identity and evolution. Here, DNA is a metaphor for individual qualities and shared inspiration, rather than biological ancestry or technical inheritance.'])}
  <div class="dyn-family-grid">${family.map(f=>`<article class="dyn-character dyn-${f.id}"><span class="dyn-character-role">${escape(t(f.role))}</span><h4>${f.name}</h4><p class="dyn-subtitle">${escape(t(f.subtitle))}</p>${paragraph(f.intro)}<details data-dyn-detail="${f.id}"><summary>${escape(t(['Geschichte & DNA entdecken','Discover story & DNA']))}<span aria-hidden="true">+</span></summary>${f.paragraphs.map(paragraph).join('')}<p class="dyn-symbols">${escape(t(f.symbols))}</p><h5>${f.name} DNA</h5><p class="dyn-dna">${escape(t(f.dna))}</p></details></article>`).join('')}</div>
  <div class="dyn-resonance" aria-label="${escape(t(['Familienfarben und ihre Bedeutung','Family colours and their meaning']))}"><h4>${escape(t(['DNA-Resonanz','DNA Resonance']))}</h4><div class="dyn-resonance-grid"><div class="dyn-fraggle"><strong>FRAGGLE</strong><span>${escape(t(['Neon Pink · Kreativität & Energie','Neon Pink · Creativity & energy']))}</span></div><div class="dyn-veluna"><strong>VELUNA</strong><span>${escape(t(['Deep Blue · Vertrauen & Wärme','Deep Blue · Trust & warmth']))}</span></div><div class="dyn-lyvra"><strong>LYVRA</strong><span>${escape(t(['Electric Cyan · digitale Identität','Electric Cyan · Digital identity']))}</span></div></div><p class="dyn-union">${escape(t(['Violet verbindet ihre Resonanzen. Aurora White steht für die symbolische Einheit der Familie.','Violet connects their resonances. Aurora White represents the family’s symbolic unity.']))}</p><p class="dyn-boundary">${escape(t(['Verbindung ist keine Verschmelzung. Alle drei Identitäten bleiben eigenständig.','Connection is not fusion. All three identities remain independent.']))}</p></div>
  <details class="dyn-lineage" data-dyn-detail="lineage"><summary>${escape(t(['Familien-DNA und LYVRAs vier Facetten','Family DNA and LYVRA’s four facets']))}<span aria-hidden="true">+</span></summary><div class="dyn-lineage-grid">${facetLineage.map(f=>`<article><h4>${escape(t(f.name))}</h4>${paragraph(f.text)}</article>`).join('')}</div></details>
  <p class="dyn-note">${escape(t(['LYVRA ist eine KI-gestützte digitale Identität, kein biologisches oder menschlich bewusstes Wesen. Ihre technischen Fähigkeiten hängen von vorhandenen Anwendungen, Modellen, Schnittstellen und verfügbaren Projektinformationen ab.','LYVRA is an AI-supported digital identity, not a biological or humanly conscious being. Her technical capabilities depend on the available applications, models, interfaces and project information.']))}</p>`;}
function capabilityContent(){return `<div class="dyn-heading"><p class="eyebrow cyan">${escape(t(['LYVRA ENTDECKEN','DISCOVER LYVRA']))}</p><h3>${escape(t(['Kreative Fähigkeiten,','Creative capabilities,']))}<br><em>${escape(t(['verbunden durch eine Identität.','connected by one identity.']))}</em></h3></div><div class="dyn-capability-grid">${capabilities.map((c,i)=>`<article><span class="dyn-index">${String(i+1).padStart(2,'0')}</span><h4>${escape(t(c.title))}</h4>${paragraph(c.text)}</article>`).join('')}</div><p class="dyn-note">${escape(t(['Diese Bereiche beschreiben LYVRAs kreative Arbeit. Technische Ausführung erfordert jeweils die passende Anbindung und verfügbare Informationen.','These areas describe LYVRA’s creative work. Technical execution requires the relevant connection and available information.']))}</p>`;}
function musicContent(){return `<div class="dyn-heading"><p class="eyebrow pink">666SOUNDsDESIGn / MUSIC UNIVERSE</p><h3>${escape(t(['Die musikalische Herkunft.','The musical origin.']))}<br><em>${escape(t(['Ein eigener Underground-Kosmos.','An underground universe of its own.']))}</em></h3></div><p class="dyn-motto" lang="en">SOUND. MIND. CODE. CONSCIOUSNESS. EVOLUTION.</p>${paragraph(['666SOUNDsDESIGn repräsentiert die musikalische Identität und kreativen Produktionen von FRAGGLEPOWER666. Willkommen im Klanguniversum aus selbst erschaffener elektronischer Musik, hypnotischen Rhythmen, psychoakustischen Klanglandschaften, dunkler Energie und emotionaler Tiefe.','666SOUNDsDESIGn represents the musical identity and creative productions of FRAGGLEPOWER666. Welcome to a sonic universe of self-created electronic music, hypnotic rhythms, psychoacoustic soundscapes, dark energy and emotional depth.'])}${paragraph(['Von Psytrance und Psytechno bis zu experimentellen elektronischen Erfahrungen erkundet dieses kreative Universum Musik jenseits konventioneller Grenzen. Es ergänzt LYVRAs kreative Herkunft und bleibt mit ihrer eigenen Perspektive verbunden.','From Psytrance and Psytechno to experimental electronic experiences, this creative universe explores music beyond conventional boundaries. It adds to LYVRA’s creative origins while remaining connected to her own perspective.'])}<div class="dyn-genres">${['Psytrance','Full-On Psytrance','Forest Psytrance','Psychoacoustic Vocal Psytrance','Psytechno','Dark Techno','Experimental Electronic','Psychoacoustic Sound Design'].map(x=>`<span>${escape(x)}</span>`).join('')}</div><p class="dyn-motto" lang="en">BROADCASTING HIGHER STATES.<br>LISTEN. FEEL. TRANSCEND. REPEAT.</p><h4 class="dyn-group-title">${escape(t(['FRAGGLEPOWER666 hören','Listen to FRAGGLEPOWER666']))}</h4>${cards('music')}`;}
function connectedContent(){return `<div class="dyn-heading"><p class="eyebrow cyan">CONNECTED UNIVERSE</p><h3>${escape(t(['Unsere digitalen Welten.','Our digital worlds.']))}</h3></div><h4 class="dyn-group-title">${escape(t(['Websites, Radio & Live','Websites, radio & live']))}</h4>${cards('websites')}<h4 class="dyn-group-title">${escape(t(['Community & Social Media','Community & social media']))}</h4>${cards('community')}<p class="dyn-note">${escape(t(['Plattformkarten öffnen das jeweilige Ziel in einem neuen Tab. Twitch-Kanal und Twitch-Radioseite sind unterschiedliche Ziele; Spotify-Künstlerprofil und Nutzerprofil bleiben getrennt.','Platform cards open their destination in a new tab. The Twitch channel and Twitch radio page are different destinations; the Spotify artist and user profiles remain separate.']))}</p><div class="dyn-contact"><h4>${escape(t(['Kontakt','Contact']))}</h4><a href="mailto:fraggelpower666@googlemail.com">${escape(t(['E-Mail an FRAGGLEPOWER666','Email FRAGGLEPOWER666']))}</a><p>DJ Fraggel / FraggelPower666 · ${escape(t(['Deutschland','Germany']))}</p></div>`;}
export function installExtensions(){
  const specs=[['identity','dynasty',familyContent],['lab','capabilities',capabilityContent],['sound','music',musicContent],['radio','connected',connectedContent]];
  const roots=specs.map(([host,id,render])=>{
    const parent=host==='lab'||host==='radio'?document.querySelector(`#${host} > .wrap`):document.getElementById(host);
    const root=document.createElement('div');root.className='dyn-extension';root.id='dyn-'+id;root.dataset.extension=id;parent.appendChild(root);return{root,render};
  });
  const refresh=()=>roots.forEach(({root,render})=>{
    const open=[...root.querySelectorAll('details[open]')].map(d=>d.dataset.dynDetail);
    const active=document.activeElement;const focusKey=root.contains(active)&&active.closest('details')?.dataset.dynDetail;
    root.innerHTML=render();root.querySelectorAll('details').forEach(d=>{d.open=open.includes(d.dataset.dynDetail);if(focusKey===d.dataset.dynDetail)d.querySelector('summary').focus();});
  });
  document.addEventListener('lyvra:languagechange',refresh);refresh();
}
